def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = float(my_status['hp'])
    budget = float(my_status['budget'])
    no_water_days = int(my_status['no_water_days'])

    if budget <= 0:
        return 0.0

    alive = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in opponents_status.values():
        if opp.get('alive'):
            alive.append(opp)
            if float(opp.get('budget', 0)) > budget:
                rich_opp += 1
            if int(opp.get('no_water_days', 0)) >= 1 or float(opp.get('hp', 0)) <= 4:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if isinstance(prev, dict) else None
            if bid is not None:
                prev_bids.append(float(bid))

    if not alive:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    competitors = len(alive) + 1
    scarcity = competitors - slots

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    my_urgent = 0
    if hp <= 3 or no_water_days >= 1:
        my_urgent = 2
    elif hp <= 5:
        my_urgent = 1

    if my_urgent >= 2:
        target = max(62.0, highest_prev + 2.0, avg_prev + 8.0)
    elif scarcity >= 3:
        target = max(52.0, avg_prev + 4.0, highest_prev * 0.72)
    elif scarcity >= 2:
        target = max(41.0, avg_prev + 2.0, highest_prev * 0.58)
    elif scarcity >= 1:
        target = max(29.0, avg_prev * 0.9, highest_prev * 0.42)
    else:
        target = 18.0 + 2.0 * urgent_opp

    if rich_opp >= 2:
        target -= 4.0
    if day >= 8 and hp >= 6 and no_water_days == 0:
        target -= 3.0
    if supply >= 24:
        target -= 4.0
    elif supply <= 16:
        target += 6.0

    reserve_days = max(1, 11 - day)
    soft_cap = budget / reserve_days + DAILY_SALARY * 0.35
    if my_urgent == 0:
        target = min(target, soft_cap)
    else:
        target = min(target, max(soft_cap, 66.0))

    target = max(8.0, target)
    bid = min(budget, target)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    hp = int(my_status.get('hp', 0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opps.append((opp_id, opp))

    if not alive_opps:
        return float(min(budget, DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    yesterday_hp_after = []
    for opp_id, opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass
            try:
                yesterday_hp_after.append(int(prev.get('hp_after', opp.get('hp', 0))))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0
    avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 0.0

    # Base target: aim slightly below the strong bidders to conserve budget.
    # If we see very high bids yesterday, we must raise to avoid losing.
    if highest_prev_bid >= DAILY_SALARY * 0.9:
        base = DAILY_SALARY * 0.75
    elif highest_prev_bid >= DAILY_SALARY * 0.65:
        base = DAILY_SALARY * 0.68
    else:
        base = DAILY_SALARY * 0.58

    # If we are under pressure (low hp or accumulating dry days), bid more.
    if hp <= 2 or no_water_days >= 2:
        base *= 1.25
    elif hp <= 4:
        base *= 1.10

    # If we are comfortably healthy, bid less.
    if hp >= 8 and no_water_days == 0:
        base *= 0.85

    # Supply-aware adjustment: with lower supply, competition is tighter.
    if supply <= float(MIN_SUPPLY):
        base *= 1.10
    elif supply >= float(MAX_SUPPLY):
        base *= 0.95

    # Ensure we don't overshoot budget.
    bid = min(budget, base)

    # Add a small increment if yesterday suggests others were just barely winning.
    # This helps us beat close contests without matching their full aggression.
    if highest_prev_bid > 0:
        # If our bid is far below their top bid, push closer.
        if bid < highest_prev_bid * 0.85:
            bid = min(budget, highest_prev_bid * 0.9)
        # If our bid is too close but still likely losing, nudge.
        if bid < highest_prev_bid and bid + 2.0 <= budget:
            bid = bid + 2.0

    # Final clamp: non-negative and not exceeding budget
    if bid < 0.0:
        bid = 0.0
    if bid > budget:
        bid = budget

    return float(bid)
